import React, { useState, useEffect } from 'react';
import { fetchTraders } from '../services/api';

export default function TradersPage() {
  const [traders, setTraders] = useState([]);
  const [search,  setSearch]  = useState('');
  const [sort,    setSort]    = useState('trust_asc');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchTraders()
      .then(d => { setTraders(Array.isArray(d) ? d : []); setLoading(false); })
      .catch(() => setLoading(false));
  }, []);

  const sorted = [...traders]
    .filter(t => t.trader_name?.toLowerCase().includes(search.toLowerCase()) || String(t.trader_id).includes(search))
    .sort((a, b) => {
      if (sort === 'trust_asc')  return (a.trust_score ?? 999) - (b.trust_score ?? 999);
      if (sort === 'trust_desc') return (b.trust_score ?? 0)   - (a.trust_score ?? 0);
      return 0;
    });

  const trustColor = (s) => s < 30 ? '#ef4444' : s < 60 ? '#f59e0b' : '#a3e635';
  const trustLabel = (s) => s < 30 ? 'HIGH RISK' : s < 60 ? 'MEDIUM' : 'LOW RISK';

  return (
    <div style={{ background: '#080808', minHeight: '100vh', padding: 32 }} className="grid-bg">
      <div style={{ maxWidth: 1200, margin: '0 auto' }}>

        <div style={{ marginBottom: 28 }}>
          <h1 style={{ fontSize: 28, fontWeight: 800, letterSpacing: '-0.02em', marginBottom: 8 }}>
            Trader <span className="neon">Registry</span>
          </h1>
          <p style={{ color: '#6b7280', fontSize: 14 }}>Dynamic trust scores updated on every suspicious trade detection</p>
        </div>

        {/* Controls */}
        <div style={{ display: 'flex', gap: 12, marginBottom: 24, flexWrap: 'wrap' }}>
          <input
            className="search-input"
            placeholder="Search by name or ID..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            style={{ maxWidth: 280 }}
          />
          <select value={sort} onChange={e => setSort(e.target.value)}
            style={{ background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.08)', color: '#fff', borderRadius: 8, padding: '9px 14px', fontSize: 13, fontFamily: 'Inter', outline: 'none', cursor: 'pointer' }}>
            <option value="trust_asc">Trust Score ↑ (Riskiest first)</option>
            <option value="trust_desc">Trust Score ↓ (Safest first)</option>
          </select>
          <div className="tag" style={{ alignSelf: 'center' }}>{sorted.length} traders</div>
        </div>

        {loading ? (
          <div style={{ textAlign: 'center', padding: 80, color: '#4b5563' }}>
            <div className="neon" style={{ fontSize: 32, marginBottom: 12 }}>⟳</div>
            <div>Loading traders...</div>
          </div>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px,1fr))', gap: 16 }}>
            {sorted.map((t, i) => (
              <div key={i} className="glass card-hover" style={{ padding: 24, borderColor: t.trust_score < 30 ? 'rgba(239,68,68,0.2)' : 'rgba(163,230,53,0.1)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16 }}>
                  <div>
                    <div style={{ fontWeight: 700, fontSize: 15, marginBottom: 3 }}>{t.trader_name}</div>
                    <div style={{ color: '#4b5563', fontSize: 11, fontFamily: 'monospace' }}>ID #{t.trader_id}</div>
                  </div>
                  <div style={{ textAlign: 'right' }}>
                    <div style={{ fontSize: 26, fontWeight: 900, color: trustColor(t.trust_score), textShadow: `0 0 10px ${trustColor(t.trust_score)}44` }}>
                      {t.trust_score ?? '—'}
                    </div>
                    <div style={{ fontSize: 9, fontWeight: 700, color: trustColor(t.trust_score), letterSpacing: '0.08em' }}>{trustLabel(t.trust_score)}</div>
                  </div>
                </div>
                {/* Trust bar */}
                <div className="progress-bar" style={{ marginBottom: 14 }}>
                  <div className={`progress-fill ${t.trust_score < 30 ? 'progress-fill-red' : ''}`} style={{ width: `${t.trust_score ?? 0}%` }} />
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
                  {[
                    { l: 'Sector',    v: t.sector        || '—' },
                    { l: 'Region',    v: t.region        || '—' },
                    { l: 'Trades',    v: t.trade_count   ?? '—' },
                    { l: 'Risk Flags',v: t.risk_flags    ?? '0' },
                  ].map((item, j) => (
                    <div key={j} style={{ background: 'rgba(0,0,0,0.3)', borderRadius: 6, padding: '6px 10px' }}>
                      <div style={{ color: '#4b5563', fontSize: 10, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em' }}>{item.l}</div>
                      <div style={{ color: '#9ca3af', fontSize: 12, fontWeight: 500, marginTop: 2 }}>{item.v}</div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
